pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz params: from address, array of tos, uint v
    function testFuzz_property(address from, address[] memory tos, uint256 v) public {
        // admissible domain: tos must be non-empty per require in C.transfer
        vm.assume(tos.length > 0);
        // Deploy a benign callee that always returns (simulates a successful external contract)
        BenignCallee cal = new BenignCallee();
        // Call c.transfer and capture whether it returns true (reference must return true)
        bool ok;
        try c.transfer(from, address(cal), tos, v) returns (bool ret) {
            ok = ret;
        } catch {
            ok = false;
        }
        // The universal property: for all admissible inputs interacting with a callee that
        // successfully handles the low-level call, the reference must return true.
        // The mutant that unconditionally returns false will cause this assertion to fail
        // for some admissible inputs (the fuzzer will find them).
        assertTrue(ok);
    }
}

// Minimal adversarial (here benign) callee that implements transferFrom and always succeeds
contract BenignCallee {
    // match selector transferFrom(address,address,uint256)
    function transferFrom(address, address, uint256) external pure returns (bool) {
        return true;
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzz the deciding inputs: from address, callee address is provided by a helper we deploy,
    // an array of target addresses, and a uint value. The fuzzer will try many combinations.
    function testFuzz_property(address from, uint256 v, address[] memory tos) public {
        // admissible domain: tos must be non-empty (the function requires this); keep wide otherwise
        vm.assume(tos.length > 0);

        // Deploy a benign helper that will accept the low-level call and return true to mimic a token contract.
        // We need an external contract because a raw EOA address would make the low-level call succeed trivially
        // but we still must route through a contract to satisfy the adversarial-counterparty rule.
        HelperReceiver helper = new HelperReceiver();

        // Call transfer on c and capture whether it returns true (completes successfully and returns true).
        bool ok;
        try c.transfer(from, address(helper), tos, v) returns (bool retval) {
            // The reference contract should return true for all admissible inputs
            ok = retval;
        } catch {
            ok = false; // any revert counts as false
        }

        // Single assertion: reference C always returns true for non-empty tos; the mutant will return false for some inputs
        assertTrue(ok);
    }
}

// Minimal helper that responds to transferFrom(address,address,uint256) via fallback and returns successfully.
contract HelperReceiver {
    // The reference C uses low-level call with selector of transferFrom(address,address,uint256).
    // We implement a fallback that returns (no revert) so the call in C succeeds.
    fallback() external payable {
        // do nothing, just accept call and return success
    }
}
